# shellcheck shell=bash
# Shared by sync.sh, select.sh, add_file.sh and promote.sh: where config dirs
# live and how a repo file is symlinked into one. Source it, don't run it.
# Kept bash 3.2 compatible (stock macOS /bin/bash).

GREEN='\033[1;32m'; YELLOW='\033[1;33m'; RED='\033[1;31m'; NC='\033[0m'
log_info() { echo -e "${GREEN}[INFO]${NC}  $*"; }
log_warn() { echo -e "${YELLOW}[WARN]${NC}  $*"; }
log_err()  { echo -e "${RED}[ERR ]${NC}  $*" >&2; }

# Never symlinked into a config dir.
#   settings.json       - generated by sync.sh, per config dir
#   settings.base.json  - source for that merge, not a file Claude Code reads
#   settings.local.json - project-scoped; Claude Code reads it from a project's
#                         .claude/, not from a user config dir
SKIP_FILES=("settings.json" "settings.base.json" "settings.local.json")

is_skipped() {
    local rel="$1" s
    for s in "${SKIP_FILES[@]}"; do
        [ "${rel}" = "${s}" ] && return 0
    done
    return 1
}

# Marker that makes an alternate ~/.claude-* folder a sync target: a file with
# this name that holds the folder's own absolute path. `./sync.sh <dir>` writes
# it. A copied backup carries the wrong path, so it is never adopted by accident.
CONFIG_MARKER=".dotfiles-config-dir"

# Set by `./sync.sh --relink`: allow moving links that point into ANOTHER
# checkout of this repo that still exists (see link_file).
RELINK="${RELINK:-0}"

# Cap on the per-link problem lines verify_links prints (the count is exact).
VERIFY_MAX_LINES=20
VERIFY_PROBLEMS=0
VERIFY_SHOWN=0

config_dir_marked() {
    [ -f "$1/${CONFIG_MARKER}" ] || return 1
    [ "$(cat "$1/${CONFIG_MARKER}")" = "$(cd "$1" && pwd -P)" ]
}

# write_config_marker <dir>: make <dir> a sync target for later bare runs.
write_config_marker() {
    cd "$1" && pwd -P > "$1/${CONFIG_MARKER}"
}

# Every CLAUDE_CONFIG_DIR profile on this machine, one per line: the default
# ~/.claude plus each alternate ~/.claude-* that carries the marker (e.g. the
# `claude-work` alias's CLAUDE_CONFIG_DIR=~/.claude-work). Unmarked folders
# (backups, ~/.claude-mem, ...) are not ours. Never creates a dir.
config_dirs() {
    local alt
    echo "${HOME}/.claude"
    for alt in "${HOME}"/.claude-*; do
        if [ -d "${alt}" ] && config_dir_marked "${alt}"; then
            echo "${alt}"
        fi
    done
    return 0
}

# WARN about unmarked ~/.claude-* folders that already hold a link of ours, so
# the one-time `./sync.sh <dir>` migration is not forgotten.
warn_unmarked_config_dirs() {
    local alt
    for alt in "${HOME}"/.claude-*; do
        [ -d "${alt}" ] || continue
        config_dir_marked "${alt}" && continue
        if [ -n "$(find "${alt}" -maxdepth 4 -type l -lname '*/.claude/*' 2>/dev/null | head -n 1)" ]; then
            log_warn "$(display_path "${alt}") holds links into this repo but is not a sync target; run ./sync.sh $(display_path "${alt}") once to adopt it."
        fi
    done
    return 0
}

# Short form of a path for log lines.
display_path() {
    if [ "${1#"${HOME}"/}" != "$1" ]; then
        # shellcheck disable=SC2088  # a literal ~ for display, not a path
        printf '~/%s\n' "${1#"${HOME}"/}"
    else
        printf '%s\n' "$1"
    fi
}

# The path of <root> inside the repo: a link is "ours" only under this name.
root_rel_of() {
    case "$1" in
        */.config/opencode) echo ".config/opencode" ;;
        *) echo ".claude" ;;
    esac
}

# link_is_ours <readlink value> <root_rel> <rel>: ownership rule. A symlink at
# <dst>/<rel> is ours when its target is absolute and ends in
# /<root_rel>/<rel>: the current checkout, or any other checkout or old
# location of this repo. Relative targets (the user's ../../.agents/skills/*
# links) and absolute targets of any other shape are never ours.
link_is_ours() {
    case "$1" in
        /*"/$2/$3") return 0 ;;
    esac
    return 1
}

# True when <dir> is the top level of a git checkout (not just inside one:
# the tests copy the tree into a temp dir that may sit inside another repo).
repo_is_checkout() {
    local top phys
    top="$(git -C "$1" rev-parse --show-toplevel 2>/dev/null)" || return 1
    phys="$(cd "$1" && pwd -P)" || return 1
    [ "${top}" = "${phys}" ]
}

# Never linked, whatever git or the disk says: backups (the timestamped .bak
# files link_file makes), editor and OS litter, and Python bytecode.
EXCLUDE_NAMES=('*.bak' '.DS_Store' '*.swp' '*.swo' '*~')

# is_excluded_path <path>: matches EXCLUDE_NAMES or sits under __pycache__.
is_excluded_path() {
    local base="${1##*/}" pat
    case "$1" in
        */__pycache__/*) return 0 ;;
    esac
    for pat in "${EXCLUDE_NAMES[@]}"; do
        # shellcheck disable=SC2053  # $pat is a glob on purpose
        if [[ "${base}" == ${pat} ]]; then
            return 0
        fi
    done
    return 1
}

# Does <dir> hold any file a sync would link (same exclusions)?
tree_has_files() {
    local f
    while IFS= read -r -d '' f; do
        is_excluded_path "${f}" || return 0
    done < <(find "$1" -type f -print0 2>/dev/null)
    return 1
}

# linkable_list <root> <item> <any> <outfile>: write the files to link under
# <item>, NUL separated, to <outfile>. Returns 1 when it cannot tell, and then
# nothing may be pruned. In a git checkout the list is what git tracks (so a
# stray file is never linked), minus EXCLUDE_NAMES. With "any" (add_file.sh and
# promote.sh link a file that is not tracked yet), or when the tree is not a
# checkout (the tests copy it), it is every file on disk, same exclusions.
# It fails closed in a checkout: a failing `git ls-files` (unreadable index) or
# an empty list for a source tree that has files (nothing staged yet) must never
# read as "nothing is expected", which would make prune remove every link.
linkable_list() {
    local root="$1" item="$2" any="${3:-}" out="$4"
    local root_rel repo_dir rel raw f pat find_args=()
    root_rel="$(root_rel_of "${root}")"
    repo_dir="${root%/"${root_rel}"}"

    if [ "${any}" != "any" ] && repo_is_checkout "${repo_dir}"; then
        rel="${item#"${repo_dir}"/}"
        raw="$(mktemp)" || return 1
        if ! git --literal-pathspecs -C "${repo_dir}" ls-files -z -- "${rel}" >"${raw}"; then
            rm -f "${raw}"
            log_err "git ls-files failed in ${repo_dir}; refusing to guess what is tracked"
            return 1
        fi
        {
            while IFS= read -r -d '' f; do
                f="${repo_dir}/${f}"
                [ -f "${f}" ] && [ ! -L "${f}" ] || continue
                is_excluded_path "${f}" && continue
                printf '%s\0' "${f}"
            done <"${raw}"
        } >"${out}"
        rm -f "${raw}"
        if [ ! -s "${out}" ] && [ "${item}" = "${root}" ] && tree_has_files "${item}"; then
            log_err "git lists no tracked files under ${item}, but it has files (nothing staged, or the index is unreadable); refusing to continue"
            return 1
        fi
    else
        for pat in "${EXCLUDE_NAMES[@]}"; do
            find_args+=('!' -name "${pat}")
        done
        find "${item}" -type f "${find_args[@]}" ! -path '*/__pycache__/*' -print0 >"${out}"
    fi
}

# linkable_files <root> <item> [any]: linkable_list to stdout, for callers that
# only list (select.sh). Callers that act on the result use linkable_list.
linkable_files() {
    local tmp
    tmp="$(mktemp)" || return 1
    if ! linkable_list "$1" "$2" "${3:-}" "${tmp}"; then
        rm -f "${tmp}"
        return 1
    fi
    cat "${tmp}"
    rm -f "${tmp}"
}

# expected_rels <root> [skip]: the paths (relative to <root>) a sync links, one
# per line. The set prune_links and verify_links compare against. Returns 1,
# printing nothing, when linkable_list cannot tell.
expected_rels() {
    local root="$1" apply_skips="${2:-}" tmp file rel
    tmp="$(mktemp)" || return 1
    if ! linkable_list "${root}" "${root}" "" "${tmp}"; then
        rm -f "${tmp}"
        return 1
    fi
    {
        while IFS= read -r -d '' file; do
            rel="${file#"${root}"/}"
            if [ "${apply_skips}" = "skip" ] && is_skipped "${rel}"; then
                continue
            fi
            printf '%s\n' "${rel}"
        done <"${tmp}"
    } | LC_ALL=C sort
    rm -f "${tmp}"
}

# warn_untracked_files <root>: in a git checkout, name the untracked files under
# <root> that a sync will not link, so a new rule that was never `git add`ed is
# visible when it bites. Litter (EXCLUDE_NAMES) is not worth a line.
warn_untracked_files() {
    local root="$1" root_rel repo_dir f shown=0 total=0
    root_rel="$(root_rel_of "${root}")"
    repo_dir="${root%/"${root_rel}"}"
    repo_is_checkout "${repo_dir}" || return 0
    while IFS= read -r -d '' f; do
        is_excluded_path "${f}" && continue
        total=$((total + 1))
        if [ "${shown}" -lt 10 ]; then
            shown=$((shown + 1))
            log_warn "Not linked, untracked: ${f}"
        fi
    done < <(git --literal-pathspecs -C "${repo_dir}" ls-files -o --exclude-standard -z -- "${root_rel}" 2>/dev/null)
    if [ "${total}" -gt "${shown}" ]; then
        log_warn "... and $((total - shown)) more untracked files under ${root_rel}"
    fi
    if [ "${total}" -gt 0 ]; then
        log_warn "Run git add on the ones you want; only tracked files are linked."
    fi
    return 0
}

# in_list <newline list> <line>: exact whole-line membership (bash 3.2 has no
# associative arrays).
in_list() {
    grep -Fxq -- "$2" <<<"$1"
}

# dir_holds_expected <expected> <rel>: is <rel> a directory that holds expected
# paths? A link there is a whole-directory link (skills -> <repo>/.claude/skills):
# the user's way of linking, not a stale per-file link, so it is left alone.
dir_holds_expected() {
    awk -v p="$2/" 'index($0, p) == 1 { found = 1 } END { exit !found }' <<<"$1"
}

# expected_is_suspect <root> <expected>: an empty expected set for a source tree
# that has files means the listing is wrong, not that nothing is wanted.
expected_is_suspect() {
    [ -z "$2" ] && tree_has_files "$1"
}

# Is a parent directory of <dst>/<rel>, inside <dst>, a symlink? Writing there
# would go through it (skills/orca-cli -> ../../.agents/skills/orca-cli).
PARENT_LINK=""
PARENT_WARNED=""
parent_is_symlink() {
    local dst="$1" rel="$2" d
    d="$(dirname "${dst}/${rel}")"
    while [ "${d}" != "${dst}" ] && [ "${d}" != "/" ] && [ "${d}" != "." ]; do
        if [ -L "${d}" ]; then
            PARENT_LINK="${d}"
            return 0
        fi
        d="$(dirname "${d}")"
    done
    return 1
}

# Print the refusal once per config dir and old checkout, not once per file.
REFUSED_SEEN=""
note_other_checkout() {
    local dst="$1" old_root="$2" new_root="$3" key
    key="|${dst}|${old_root}|"
    case "${REFUSED_SEEN}" in
        *"${key}"*) return 0 ;;
    esac
    REFUSED_SEEN="${REFUSED_SEEN}${key}"
    log_err "$(display_path "${dst}"): linked to ${old_root}, this run is ${new_root}; re-run with --relink to move it"
}

# backup_name <file>: <file>.<YYYYMMDD-HHMMSS>.bak, with .<n> before .bak when
# that name is taken. Still ends in .bak, so it stays gitignored and unlinked.
backup_name() {
    local base cand n=1
    base="$1.$(date +%Y%m%d-%H%M%S)"
    cand="${base}.bak"
    while [ -e "${cand}" ] || [ -L "${cand}" ]; do
        n=$((n + 1))
        cand="${base}.${n}.bak"
    done
    printf '%s\n' "${cand}"
}

# link_file <src> <dst> <rel> <root_rel>: make <dst>/<rel> a symlink to <src>.
#   - already a link to <src>: nothing to do
#   - a link of ours (see link_is_ours) to somewhere else:
#       old target gone (moved/deleted checkout): repoint, logging the old one
#       old target still exists in another checkout: refuse unless RELINK=1
#   - a link that is not ours: kept, with a WARN
#   - a regular file: moved to a timestamped .bak first
#   - a parent directory inside <dst> is a symlink: skipped, with a WARN
link_file() {
    local src="$1" dst="$2" rel="$3" root_rel="$4"
    local target="${dst}/${rel}" old old_root backup

    if parent_is_symlink "${dst}" "${rel}"; then
        case "${PARENT_WARNED}" in
            *"|${PARENT_LINK}|"*) ;;
            *)
                PARENT_WARNED="${PARENT_WARNED}|${PARENT_LINK}|"
                log_warn "Not linking under $(display_path "${PARENT_LINK}"): it is a symlink"
                ;;
        esac
        return 0
    fi

    mkdir -p "$(dirname "${target}")"
    if [ -L "${target}" ]; then
        old="$(readlink "${target}")"
        if [ "${old}" = "${src}" ] || [ "${old}" -ef "${src}" ]; then
            return 0
        fi
        if ! link_is_ours "${old}" "${root_rel}" "${rel}"; then
            log_warn "Keeping $(display_path "${target}") -> ${old}: points outside this repo"
            return 0
        fi
        if [ -e "${target}" ] && [ "${RELINK}" != "1" ]; then
            old_root="${old%"/${root_rel}/${rel}"}"
            note_other_checkout "${dst}" "${old_root}" "${src%"/${root_rel}/${rel}"}"
            return 0
        fi
        rm "${target}"
        log_warn "Repointing $(display_path "${target}") (was -> ${old})"
    elif [ -e "${target}" ]; then
        backup="$(backup_name "${target}")"
        log_warn "Backing up existing file: $(display_path "${target}") -> $(basename "${backup}")"
        mv "${target}" "${backup}"
    fi

    ln -s "${src}" "${target}"
    log_info "Linked: $(display_path "${target}")"
}

# link_under <root> <item> <dst> [skip] [any]: symlink <item> (one file, or
# every file under a directory) into <dst>, keeping its path relative to <root>.
# With "skip" as the fourth argument, SKIP_FILES are left out. See
# linkable_files for what is linked and for "any".
link_under() {
    local root="$1" item="$2" dst="$3" apply_skips="${4:-}" any="${5:-}" file rel root_rel tmp
    root_rel="$(root_rel_of "${root}")"
    tmp="$(mktemp)" || return 1
    if ! linkable_list "${root}" "${item}" "${any}" "${tmp}"; then
        rm -f "${tmp}"
        return 1
    fi

    while IFS= read -r -d '' file; do
        rel="${file#"${root}"/}"
        if [ "${apply_skips}" = "skip" ] && is_skipped "${rel}"; then
            continue
        fi
        link_file "${file}" "${dst}" "${rel}" "${root_rel}"
    done <"${tmp}"
    rm -f "${tmp}"
}

# Remove now-empty directories from <dir> up to (not including) <dst>.
prune_empty_dirs() {
    local dst="$1" dir="$2"
    while [ "${dir}" != "${dst}" ] && rmdir "${dir}" 2>/dev/null; do
        dir="$(dirname "${dir}")"
    done
}

# prune_links <root> <dst> <root_rel> <expected>: remove symlinks of ours under
# <dst> that a sync no longer links: the repo file was deleted, moved, skipped
# (settings.local.json) or is untracked. Only ever `rm`s symlinks, never a file
# in the repo. Links into another checkout that still exists are kept with a
# WARN, unless RELINK=1. The top-level settings.json is left to merge_settings.
prune_links() {
    local root="$1" dst="$2" root_rel="$3" expected="$4" link rel old
    [ -d "${dst}" ] || return 0
    if expected_is_suspect "${root}" "${expected}"; then
        log_err "Refusing to prune $(display_path "${dst}"): the repo lists no files to link, but ${root} has files"
        return 1
    fi

    while IFS= read -r -d '' link; do
        rel="${link#"${dst}"/}"
        [ "${rel}" = "settings.json" ] && continue
        old="$(readlink "${link}")"
        link_is_ours "${old}" "${root_rel}" "${rel}" || continue
        in_list "${expected}" "${rel}" && continue
        if dir_holds_expected "${expected}" "${rel}"; then
            log_warn "Keeping $(display_path "${link}") -> ${old}: a whole-directory link into the repo"
            continue
        fi

        if [ "${old}" = "${root}/${rel}" ] || [ ! -e "${link}" ] || [ "${RELINK}" = "1" ]; then
            rm "${link}"
            log_warn "Pruned link: $(display_path "${link}")"
            prune_empty_dirs "${dst}" "$(dirname "${link}")"
        else
            log_warn "Keeping $(display_path "${link}") -> ${old}: another checkout still holds it (--relink removes it)"
        fi
    done < <(find "${dst}" -type l -print0)
    return 0
}

verify_problem() {
    VERIFY_PROBLEMS=$((VERIFY_PROBLEMS + 1))
    if [ "${VERIFY_SHOWN}" -lt "${VERIFY_MAX_LINES}" ]; then
        VERIFY_SHOWN=$((VERIFY_SHOWN + 1))
        log_err "$*"
    fi
}

# verify_links <root> <dst> <root_rel> <expected> [info]: read-only. Returns 1
# when <dst> does not match the repo: an expected link is missing, is a plain
# file, or is a link of ours to the wrong place, or one of ours is dangling.
# Links that are not ours (user links, Claude Code's debug/latest) never fail
# it; with a fifth argument they are reported as WARNs.
verify_links() {
    local root="$1" dst="$2" root_rel="$3" expected="$4" info="${5:-}" rel link old
    VERIFY_PROBLEMS=0
    VERIFY_SHOWN=0

    if expected_is_suspect "${root}" "${expected}"; then
        verify_problem "$(display_path "${dst}"): the repo lists no files to link, but ${root} has files"
    fi

    while IFS= read -r rel; do
        [ -n "${rel}" ] || continue
        link="${dst}/${rel}"
        if parent_is_symlink "${dst}" "${rel}"; then
            [ -n "${info}" ] && log_warn "$(display_path "${link}"): a parent directory is a symlink, not linked"
            continue
        fi
        if [ -L "${link}" ]; then
            old="$(readlink "${link}")"
            if [ "${old}" = "${root}/${rel}" ] || [ "${old}" -ef "${root}/${rel}" ]; then
                continue
            elif ! link_is_ours "${old}" "${root_rel}" "${rel}"; then
                [ -n "${info}" ] && log_warn "$(display_path "${link}") -> ${old}: points outside the repo"
            elif [ -e "${link}" ]; then
                VERIFY_PROBLEMS=$((VERIFY_PROBLEMS + 1))
                note_other_checkout "${dst}" "${old%"/${root_rel}/${rel}"}" "${root%"/${root_rel}"}"
            else
                verify_problem "$(display_path "${link}") -> ${old}: stale, the target is gone"
            fi
        elif [ -e "${link}" ]; then
            verify_problem "$(display_path "${link}"): a plain file, not a link into the repo"
        else
            verify_problem "$(display_path "${link}"): missing"
        fi
    done <<<"${expected}"

    if [ -d "${dst}" ]; then
        while IFS= read -r -d '' link; do
            rel="${link#"${dst}"/}"
            [ "${rel}" = "settings.json" ] && continue
            in_list "${expected}" "${rel}" && continue
            old="$(readlink "${link}")"
            if link_is_ours "${old}" "${root_rel}" "${rel}" && dir_holds_expected "${expected}" "${rel}"; then
                [ -n "${info}" ] && log_warn "$(display_path "${link}") -> ${old}: a whole-directory link into the repo"
                continue
            fi
            if ! link_is_ours "${old}" "${root_rel}" "${rel}"; then
                [ -e "${link}" ] || log_warn "$(display_path "${link}") -> ${old}: dangling, but not a link of ours (kept)"
            elif [ ! -e "${link}" ]; then
                verify_problem "$(display_path "${link}") -> ${old}: dangling link of ours"
            elif [ "${old}" = "${root}/${rel}" ]; then
                verify_problem "$(display_path "${link}"): no longer linked by the repo, a sync prunes it"
            else
                [ -n "${info}" ] && log_warn "$(display_path "${link}") -> ${old}: another checkout still holds it"
            fi
        done < <(find "${dst}" -type l -print0)
    fi

    if [ "${VERIFY_PROBLEMS}" -gt 0 ]; then
        log_err "$(display_path "${dst}"): ${VERIFY_PROBLEMS} link problem(s) in total"
    fi
    [ "${VERIFY_PROBLEMS}" -eq 0 ]
}

# stage_in_repo <repo_dir> <rel>: `git add` (no commit) the files of a path
# under .claude that add_file.sh or promote.sh just moved in, so the next sync's
# tracked-files walk keeps their links. Stages only what that walk would link,
# never a whole directory (which would track a .DS_Store inside it). Prints what
# was staged.
stage_in_repo() {
    local repo_dir="$1" rel="$2" tmp f staged=0
    if ! repo_is_checkout "${repo_dir}"; then
        log_warn "${repo_dir} is not a git checkout; not staging .claude/${rel}."
        return 0
    fi
    tmp="$(mktemp)" || return 1
    if ! linkable_list "${repo_dir}/.claude" "${repo_dir}/.claude/${rel}" any "${tmp}"; then
        rm -f "${tmp}"
        return 1
    fi
    while IFS= read -r -d '' f; do
        if git -C "${repo_dir}" add -- "${f}"; then
            staged=$((staged + 1))
        else
            log_warn "git add failed for ${f}; stage it before the next sync or its link is pruned."
        fi
    done <"${tmp}"
    rm -f "${tmp}"
    log_info "Staged: .claude/${rel} (${staged} file(s))"
}
